"use client";

import { Multislider as MultisliderPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const multisliderVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-48",
      lg: "h-64",
      sm: "h-40",
      xl: "h-96",
    },
  },
});

interface MultisliderProps
  extends MultisliderPrimitive.RootProps,
    VariantProps<typeof multisliderVariants> {
  thumbs?: "visible" | "hidden";
}

export function Multislider({
  className,
  size,
  thumbs = "hidden",
  ...props
}: MultisliderProps) {
  return (
    <MultisliderPrimitive.Root
      className={cn(
        "w-full data-[disabled=true]:cursor-not-allowed",
        className
      )}
      {...props}
    >
      <MultisliderPrimitive.Track
        className={cn(
          "rounded-2xl border border-transparent bg-card ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-4 hover:ring-ring/50 has-[:focus-visible]:ring-4 has-[:focus-visible]:ring-ring/50 active:ring-4 active:ring-ring/50 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none relative flex w-full cursor-crosshair touch-none select-none overflow-hidden",
          "gap-px data-[orientation=horizontal]:flex-col",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          multisliderVariants({ size })
        )}
        data-slot="multislider"
      >
        <MultisliderPrimitive.Sliders>
          {(_value, index) => (
            <MultisliderPrimitive.Slider
              className="outline-none focus-visible:bg-ring/10 focus-visible:ring-1 focus-visible:ring-ring/60 focus-visible:ring-inset relative flex-1 outline-none"
              index={index}
              key={`multislider-slider-${index}`}
            >
              <MultisliderPrimitive.Fill className="bg-primary absolute inset-0" />
              {thumbs === "visible" ? (
                <MultisliderPrimitive.Thumb className="bg-foreground/70 absolute data-[orientation=horizontal]:top-0 data-[orientation=horizontal]:bottom-0 data-[orientation=horizontal]:w-0.5 data-[orientation=vertical]:right-0 data-[orientation=vertical]:left-0 data-[orientation=vertical]:h-0.5" />
              ) : null}
            </MultisliderPrimitive.Slider>
          )}
        </MultisliderPrimitive.Sliders>
      </MultisliderPrimitive.Track>
    </MultisliderPrimitive.Root>
  );
}
